import math,json
max_error=0.0; cases=0
for d in (8,64,128):
    q=[math.sin(i+0.3) for i in range(d)]
    k=[math.cos(i+0.7) for i in range(d)]
    for pos in (0,1,255,8192):
        for a in (1.0,1.25):
            rq=[0.0]*d; rk=[0.0]*d
            for t in range(d//2):
                angle=pos/(10000.0**(2*t/d))
                s=math.sin(angle)*a; c=math.cos(angle)*a
                for v,r in ((q,rq),(k,rk)):
                    r[t]=v[t]*c-v[t+d//2]*s
                    r[t+d//2]=v[t+d//2]*c+v[t]*s
            error=abs(sum(x*y for x,y in zip(rq,rk))-a*a*sum(x*y for x,y in zip(q,k)))
            max_error=max(max_error,error); cases+=1
            assert error<1e-12
P=256; B=2; C=512; H=2; D=8
checks=0
for b in range(B):
    for t in range(C):
        page=b*(C//P)+t//P
        for h in range(H):
            for j in range(D):
                paged=((page*P+t%P)*H+h)*D+j
                contiguous=((b*C+t)*H+h)*D+j
                assert paged==contiguous
                checks+=1
partial=[]
for d,pd in ((128,128),(128,64)):
    writes=[]
    for t in range(d//2):
        writes.extend((t,t+pd//2) if t<pd//2 else (2*t,2*t+1))
    assert sorted(writes)==list(range(d))
    partial.append({'head_dim':d,'partial_head_dim':pd,'writes_cover_head_once':True,'inv_freq_length':pd//2,'unconditional_frequency_indices_outside_length':sum(t>=pd//2 for t in range(d//2))})
print(json.dumps({'rope_dot_product_cases':cases,'max_double_precision_error':max_error,'paged_vs_contiguous_offsets_checked':checks,'partial_rope_index_analysis':partial,'environment':'standard-library CPU scalar and integer-index checks; not torch, CUDA, FP16, fast sin/cos, or a memory-safety test'}))

