import struct, math, json
cases=0
for m in range(1,9):
 for k in range(1,9):
  for n in range(1,9):
   a=[(i%7)-3 for i in range(m*k)]; b=[(i%5)-2 for i in range(k*n)]
   row=[sum(a[i*k+t]*b[t*n+j] for t in range(k)) for i in range(m) for j in range(n)]
   col=[0]*(m*n)
   for i in range(n):
    for j in range(m): col[i+j*n]=sum(b[i+t*n]*a[t+j*k] for t in range(k))
   assert row==col
   cases+=1
cap=256; reallocs=0
for end in range(1,4097):
 if end>=cap: cap=(end//256+1)*256; reallocs+=1
 assert cap%256==0 and 0<cap-end<=256
halfmax=struct.unpack('<e',bytes.fromhex('ff7b'))[0]
assert halfmax==(2-2**-10)*2**15==65504
activation={str(n):list(range(2*(n//2),n)) for n in [1,3,512,513]}
softcap={}
for n in [1,3,2049]:
 blocks=((n//2)+1023)//1024
 accesses=[j for t in range(blocks*1024) if 2*t<n for j in (2*t,2*t+1)]
 softcap[str(n)]={'missed':sorted(set(range(n))-set(accesses)), 'out_of_bounds': [j for j in accesses if j>=n]}
print(json.dumps({'hgemm_layout_cases':cases,'seq_append_steps':4096,'seq_reallocations':reallocs,'seq_final_capacity':cap,'half_max':halfmax,'sqrt_2_over_pi':math.sqrt(2/math.pi),'activation_unwritten_indices':activation,'softcap_half_indexing':softcap}))

